class Solution:
    def minIncrements(self, n: int, cost: list[int]) -> int:
        ans = 0
        for i in range(n // 2 - 1, -1, -1):
            left = 2 * i + 1
            right = 2 * i + 2
            ans += abs(cost[left] - cost[right])
            cost[i] += max(cost[left], cost[right])
        return ans

class Solution {
public:
    int minIncrements(int n, std::vector<int>& cost) {
        int ans = 0;
        for (int i = n / 2 - 1; i >= 0; i--) {
            int left = 2 * i + 1, right = 2 * i + 2;
            ans += std::abs(cost[left] - cost[right]);
            cost[i] += std::max(cost[left], cost[right]);
        }
        return ans;
    }
};

