var minIncrements = function(n, cost) {
    let ans = 0;
    for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
        const left = 2 * i + 1, right = 2 * i + 2;
        ans += Math.abs(cost[left] - cost[right]);
        cost[i] += Math.max(cost[left], cost[right]);
    }
    return ans;
};
